// redis-shard-router.ts
import Redis from "ioredis";

// Fixed list of Redis nodes the cache is spread across.
const nodes: Redis[] = [
  new Redis({ host: "10.0.0.1", port: 6379 }),
  new Redis({ host: "10.0.0.2", port: 6379 }),
  new Redis({ host: "10.0.0.3", port: 6379 }),
];

const nodeCount = nodes.length;

// Simple string hash used to pick a shard.
function hashKey(key: string): number {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  }
  return hash;
}

export class RedisShardRouter {
  // Mod-N routing: which node owns this key right now.
  getNodeFor(key: string): Redis {
    const index = hashKey(key) % nodeCount;
    return nodes[index];
  }

  buildProfileKey(userId: string): string {
    return `user:${userId}:profile`;
  }

  buildCartKey(userId: string): string {
    return `user:${userId}:cart`;
  }

  async getProfile(userId: string): Promise<string | null> {
    const key = this.buildProfileKey(userId);
    return this.getNodeFor(key).get(key);
  }

  async getCart(userId: string): Promise<string | null> {
    const key = this.buildCartKey(userId);
    return this.getNodeFor(key).get(key);
  }

  // Updates a user's profile and cart together in one transaction.
  // Assumes both keys resolve to the same node, so a single MULTI
  // opened on the profile's node can also cover the cart key.
  async atomicUpdate(
    userId: string,
    profileData: string,
    cartData: string,
  ): Promise<void> {
    const profileKey = this.buildProfileKey(userId);
    const cartKey = this.buildCartKey(userId);

    const node = this.getNodeFor(profileKey);

    const multi = node.multi();
    multi.set(profileKey, profileData);
    multi.set(cartKey, cartData);
    await multi.exec();
  }
}

